/* Additive local shell using the existing admin navigation vocabulary. */
(function(){
const groups=[
 ['Counts','chart',[['Herd Analytics','/counts/analytics'],['Counts Breakdown','/counts/breakdown'],['Herd Operations SOP','/counts/sops']]],
 ['Weighing','scale',[['ADG Analytics','/weighing/analytics'],['Weighing SOP','/weighing/sops']]],
 ['Sales','wallet',[['Summary','/sales/sold'],['Farm value','/sales/farm-value'],['Load wise','/sales/loads'],['Market analytics','/sales/market-analytics'],['Buyer analytics','/sales/buyer-analytics'],['Vendors','/sales/vendors'],['Sales Config','/sales/config']]],
 ['Feed','leaf',[['Feed Config','/feed/config'],['Feed Analytics','/feed/analytics'],['Feed SOP','/feed/sops']]],
 ['Preventive Care','heart',[['Vaccination','/vaccination'],['Live Drive Tracker','/vaccination/live-tracker'],['Vaccination plan','/vaccination/plan']]],
 ['Procurement','truck',[['Source Entry','/procurement/source-entry'],['Vendors','/procurement/vendors'],['Feed Purchases','/procurement/feed-purchases'],['Animal purchases','/procurement/animal-purchases'],['Procurement SOP','/procurement/sops']]],
 ['Health','health',[['Health Analytics','/health/analytics'],['Health Config','/health/config']]],
 ['Others','edit',[['Milk Preparation','/counts/milk-preparation'],['Milk SOP','/milk/sops'],['Live Monitor','/herd-signals'],['Audit Log','/operations/audit'],['People / HRMS','/people'],['Leave','/leave']]],
 ['Configuration','settings',[['Items and settings','/configuration/items'],['Work instructions','/configuration/work-instructions']]]];
const top=[['Approvals','/approvals','check'],['Verify','/verify','check'],['Tasks','/tasks','list'],['Work Board','/work-board','board'],['Alerts','/alerts','list']];
const icons={chart:'M4 20V5m0 15h16M8 16v-5m5 5V7m5 9v-7',scale:'M12 3v17M6 20h12M4 7h16M6 7l-3 6h6l-3-6m12 0-3 6h6l-3-6',wallet:'M3 6h18v13H3zM3 6l12-3v3m2 6h4',leaf:'M5 19c-3-8 2-14 15-15 0 12-6 17-15 15zm0 0L16 8',heart:'M12 20S2 14 2 8c0-5 7-6 10-1 3-5 10-4 10 1 0 6-10 12-10 12zM5 12h4l2-4 2 8 2-4h4',truck:'M2 5h12v12H2zM14 10h5l3 4v3h-8M7 19a2 2 0 1 0 0-4 2 2 0 0 0 0 4zm11 0a2 2 0 1 0 0-4 2 2 0 0 0 0 4z',health:'M5 3v6a5 5 0 0 0 10 0V3M3 3h4m6 0h4m-7 11v3a5 5 0 0 0 10 0v-3m0 0a2 2 0 1 0 0-4 2 2 0 0 0 0 4z',edit:'m4 16-1 5 5-1L21 7l-5-5L4 16z',settings:'M12 3v3m0 12v3M3 12h3m12 0h3M6 6l2 2m8 8 2 2M6 18l2-2m8-8 2-2M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8z',check:'m5 12 4 4L20 5M17 13v7H3V6h8',list:'M6 3h12v18H6zM9 8h6m-6 4h6m-6 4h6',board:'M3 4h18v16H3zM7 8v8m5-8v5m5-5v8'};
const icon=k=>`<svg class="prod-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[k]||icons.list}"/></svg>`;
const routes=[...top.map(([label,path,key])=>({module:'Workspace',label,path,icon:key})),...groups.flatMap(([module,key,leaves])=>leaves.map(([label,path])=>({module,label,path,icon:key})))];
window.productionRoutes=routes;
const aliases={'/configuration/tools':'/configuration/work-instructions','/configuration/workflow-links':'/configuration/work-instructions','/configuration/run-insights':'/configuration/work-instructions','/configuration/connect-related-work':'/configuration/work-instructions'};
const findRoute=path=>routes.find(r=>r.path===(aliases[path]||path));
let route=findRoute(location.hash.slice(1))||routes.find(r=>r.label==='Items and settings');
let opens={Counts:false,Weighing:false,Sales:false,Feed:false,'Preventive Care':false,Procurement:false,Health:false,Others:false,Configuration:true};
let rail=false,account=false,mobileMenu=false,scope='All parks';
window.productionScope=()=>scope;
window.productionCurrentRoute=()=>({...route});
const oldRender=render,oldGo=go;
function setTarget(r){if(r.module==='Configuration'){current=r.label==='Items and settings'?'Items':'Common';tab=r.label==='Items and settings'?'Registry':'Work instructions';}else {current=r.module==='Workspace'?'Others':r.module;tab=r.label.endsWith('SOP')?'SOPs':'Production';}}
function restoreEditorHash(){let parts;try{parts=decodeURIComponent(location.hash.slice(1)).split('/');}catch{return false;}if(parts.length===2&&parts[1]==='Editor'&&state.sops?.[parts[0]]){current=parts[0];tab='Editor';route=routes.find(r=>r.module===current&&r.label.endsWith('SOP'))||routes.find(r=>r.module===current)||route;opens[route.module]=true;return true;}return false;}
function navLink(r,sub){return `<a class="prod-nav-link ${sub?'prod-sub':''} ${route.path===r.path?'active':''}" href="#${r.path}" ${route.path===r.path?'aria-current="page"':''} onclick="event.preventDefault();productionNavigate('${r.module}','${r.label}')" title="${esc(r.label)}">${sub?'<span class="prod-dot" aria-hidden="true">•</span>':icon(r.icon)}<span class="prod-nav-text">${esc(r.label)}</span></a>`;}
function shell(){document.body.classList.add('production-shell');document.body.classList.toggle('production-rail',rail);document.body.classList.toggle('production-mobile-menu',mobileMenu);document.body.classList.remove('collapsed');const role=$('#role')?.value||'CEO / CXO';document.querySelector('header').innerHTML=`<button class="prod-hamb" onclick="productionToggleRail()" aria-label="${rail||(window.innerWidth<=760&&!mobileMenu)?'Expand':'Collapse'} navigation" aria-expanded="${!rail&&(window.innerWidth>760||mobileMenu)}">☰</button><div class="brand"><span>मे</span><b>Mesha</b></div><div class="spacer"></div><span class="prod-local">Local prototype</span><label class="prod-scope"><span class="sr-only">Park scope</span><select aria-label="Park scope" onchange="productionSetScope(this.value)">${['All parks','CPT','CBE'].map(x=>`<option ${x===scope?'selected':''}>${x}</option>`).join('')}</select></label><button class="prod-theme" onclick="productionTheme()" aria-label="Switch to ${document.documentElement.classList.contains('light')?'dark':'light'} theme">☼</button><button class="prod-notifications" disabled aria-label="Notifications are not wired in this prototype">♧</button><button class="prod-account" onclick="productionToggleAccount()" aria-expanded="${account}" aria-controls="prod-account-menu"><span class="prod-avatar">CX</span><span><b>${esc(role)}</b><small>tenant scope · 2 active parks</small></span><span>›</span></button><div id="prod-account-menu" class="prod-account-menu" ${account?'':'hidden'}><label>Preview role<select id="role" aria-label="Role" onchange="productionSetRole(this.value)">${['CEO / CXO','Director','Operator'].map(x=>`<option ${role===x?'selected':''}>${x}</option>`).join('')}</select></label><p>Local permission preview only.</p></div>`;
$('#nav').innerHTML=`<nav aria-label="Main navigation">${top.map(([label])=>navLink(routes.find(r=>r.module==='Workspace'&&r.label===label),false)).join('')}${groups.map(([module,key])=>`<section class="prod-group"><button class="prod-group-button" onclick="productionToggleGroup('${module}')" aria-expanded="${!!opens[module]&&!rail&&(window.innerWidth>760||mobileMenu)}" aria-controls="prod-group-${module.replaceAll(' ','-')}" title="${module}">${icon(key)}<span class="prod-nav-text">${module}</span><span class="prod-chevron">${opens[module]?'⌄':'›'}</span></button><div id="prod-group-${module.replaceAll(' ','-')}" ${opens[module]&&!rail?'':'hidden'}>${routes.filter(r=>r.module===module).map(r=>navLink(r,true)).join('')}</div></section>`).join('')}</nav><div class="prod-nav-footer">Mesha · goat operating system</div>`;document.querySelectorAll('.foundation-path').forEach(x=>x.remove());}
window.productionToggleGroup=function(module){if(window.innerWidth<=760&&!mobileMenu){mobileMenu=true;opens[module]=true;shell();return;}if(rail){productionNavigate(module,routes.find(r=>r.module===module).label);return;}opens[module]=!opens[module];shell();};
window.productionToggleRail=function(){if(window.innerWidth<=760)mobileMenu=!mobileMenu;else rail=!rail;shell();};
window.productionToggleAccount=function(){account=!account;shell();};
window.productionSetRole=function(value){account=false;render();};
window.productionSetScope=function(value){scope=value;render();};
window.productionTheme=function(){document.documentElement.classList.toggle('light');shell();};
function reference(){const title=route.label;$('#content').innerHTML=`<section class="card prod-reference"><h2>${esc(title)}</h2><p>This existing page is preserved in the navigation. Its working data and full interactions are not reproduced in this local prototype.</p><p>Use the module's configuration and SOP screens to explore the proposed additions. No live data is shown or changed here.</p><a class="prod-open-live" href="https://dashboard.mesha.sg${route.path}" target="_blank" rel="noopener noreferrer">Open existing ${esc(title)} page ↗</a></section>`;}
render=function(){const legacy=tab==='Editor'||route.module==='Configuration'||route.label.endsWith('SOP');if(legacy){oldRender();if(tab!=='Editor'&&route.label.endsWith('SOP')){const h=$('#main h1');if(h)h.textContent=route.label;const eyebrow=$('#main .eyebrow');if(eyebrow)eyebrow.textContent=route.module+' · '+route.label;}}else{document.body.classList.remove('editorpage');$('#main').innerHTML=`<div class="prod-page-heading"><div class="eyebrow">${esc(route.module)} · ${esc(route.label)}</div><h1>${esc(route.label)}</h1></div><div id="content"></div>`;if(typeof window.renderConsumerSurface!=='function'||!window.renderConsumerSurface(route.module,route.label))reference();}shell();revealActiveTab();if(typeof requestAnimationFrame==='function')requestAnimationFrame(revealActiveTab);};
function revealActiveTab(){const strip=document.querySelector("#main .tabs"),active=strip?.querySelector?.(".active");if(strip&&active){const sr=strip.getBoundingClientRect(),ar=active.getBoundingClientRect();if(ar.right>sr.right)strip.scrollLeft+=ar.right-sr.right+8;else if(ar.left<sr.left)strip.scrollLeft-=sr.left-ar.left+8;};}
window.addEventListener('resize',revealActiveTab);
window.productionNavigate=function(module,label){label=({'Items Config':'Items and settings','Reusable tools':'Work instructions','Workflow links':'Work instructions','Run insights':'Work instructions','Connect related work':'Work instructions'})[label]||label;const next=routes.find(r=>r.module===module&&r.label===label);if(!next)return false;route=next;opens[module]=true;account=false;mobileMenu=false;history.replaceState(null,'','#'+route.path);setTarget(route);render();const main=document.querySelector('#main');if(main)main.scrollTop=0;if(typeof window.scrollTo==='function')window.scrollTo(0,0);return true;};
go=function(module,page){if(page==='Editor'){if(route.module!==module){route=routes.find(r=>r.module===module&&r.label.endsWith('SOP'))||route;}oldGo(module,page);return;}let next=module==='Items'?routes.find(r=>r.label==='Items and settings'):module==='Common'?routes.find(r=>r.label==='Work instructions'):routes.find(r=>r.module===module&&r.label.endsWith('SOP'));if(next){route=next;opens[route.module]=true;}if(module==='Common'){current=module;tab=['Connect related work','Workflow links','Run insights'].includes(page)?'Work instructions':page||'Work instructions';history.replaceState(null,'','#'+route.path);render();return;}if(next)productionNavigate(next.module,next.label);else oldGo(module,page);};
window.addEventListener('hashchange',()=>{if(restoreEditorHash()){render();return;}const next=findRoute(location.hash.slice(1));if(next){route=next;opens[route.module]=true;setTarget(route);render();}});
// The legacy DOM-ready bootstrap resets current/tab using old hash syntax.
// Reapply the selected modern route after it finishes.
window.addEventListener('DOMContentLoaded',()=>{if(!restoreEditorHash())setTarget(route);opens[route.module]=true;render();});
if(!restoreEditorHash())setTarget(route);opens[route.module]=true;render();
})();
